select e.*, c.company_name from risk_event e
left join risk_company c on e.company_id = c.id
where e.id = #{id}

select e.*, c.company_name from risk_event e
left join risk_company c on e.company_id = c.id

    AND e.company_id = #{companyId}
    AND e.event_type = #{eventType}
    AND e.severity = #{severity}
    AND e.is_read = #{isRead}
    AND e.is_handled = #{isHandled}

order by e.create_time desc

